public static int computeWithBinarySearch(int[] nums) {
    int left = 0;
    int right = nums.length - 1;

    while (left < right) {
        int mid = left + (right - left) / 2;
        if (nums[mid] > nums[right]) {
            left = mid + 1;
        } else {
            right = mid;
        }
    }
    return nums[left];
}

public static int computeWithLinearSearch(int[] nums) {
    int min = nums[0];
    for (int num : nums) {
        if (num < min) {
            min = num;
        }
    }
    return min;
}

